import assert from 'node:assert/strict'

export async function checkMeetingAnswerPages({ ev, click, change, frames, wait, send, shot }) {
  const back = async () => { await ev("document.querySelector('button[aria-label=\"Câu trả lời trước\"]').click()"); await frames() }
  const next = async () => { await ev("document.querySelector('button[aria-label=\"Câu trả lời tiếp theo\"]').click()"); await frames() }
  const text = () => ev("document.querySelector('.meeting-answer-content')?.textContent")
  const count = await ev("Number(document.querySelector('.meeting-answer-pages span').textContent.split('/')[1])")
  await ev("window.fixture.answerText='SAVED PAGE ONE';window.fixture.answerModel='page-one-model'")
  await click('Answer'); await wait("document.querySelector('.meeting-answer-content')?.textContent.includes('SAVED PAGE ONE')")
  await ev("window.fixture.answerText='SAVED PAGE TWO';window.fixture.answerModel='page-two-model'")
  await click('Answer'); await wait("document.querySelector('.meeting-answer-content')?.textContent.includes('SAVED PAGE TWO')")
  assert.equal(await ev("document.querySelector('.meeting-answer-pages span').textContent"), `${count + 2} / ${count + 2}`)
  await back(); assert.ok((await text()).includes('SAVED PAGE ONE')); assert.ok((await text()).includes('page-one-model'))
  await next(); assert.ok((await text()).includes('SAVED PAGE TWO')); assert.ok((await text()).includes('page-two-model'))
  await ev("Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async text=>{window.fixture.copiedPage=text}}})")
  await click('Copy'); await frames(); assert.equal(await ev('window.fixture.copiedPage'), 'SAVED PAGE TWO')
  await back(); assert.equal(await ev("[...document.querySelectorAll('.meeting-actions button')].some(b=>b.textContent.includes('Đã copy'))"), false)
  await click('Thu gọn'); await wait("document.querySelector('button[title=\"Expand\"]')")
  await ev("document.querySelector('button[title=\"Expand\"]').click()"); await frames()
  assert.ok((await text()).includes('SAVED PAGE ONE'), 'Selected history page survives collapse')
  await click('Lịch sử'); await wait("!document.querySelector('.meeting-toolbar')")
  await click('Đóng'); await wait("document.querySelector('.meeting-toolbar')")
  assert.ok((await text()).includes('SAVED PAGE ONE'), 'Selected page survives transcript-history screen')
  await click('Chat'); await frames()
  await change('.meeting-composer textarea', 'Explain the next code sample')
  await ev("window.fixture.delayQuestion=true;window.fixture.answerText='SAVED PAGE THREE';window.fixture.answerModel='page-three-model';delete window.fixture.releaseQuestion")
  await click('Gửi câu hỏi'); await wait('window.fixture.releaseQuestion')
  assert.equal(await ev("document.querySelector('.meeting-answer-pages span').textContent.includes('Đang soạn')"), true)
  await back(); await back(); assert.ok((await text()).includes('SAVED PAGE ONE'))
  await ev("window.fixture.reply({reply:'More preview chunks',partial:true})"); await frames()
  assert.ok((await text()).includes('SAVED PAGE ONE'), 'Streaming cannot overwrite the saved page being read')
  await ev('window.fixture.delayQuestion=false;window.fixture.releaseQuestion()'); await wait("document.querySelector('.meeting-composer textarea').value===''")
  assert.ok((await text()).includes('SAVED PAGE ONE'), 'Completion does not steal focus while browsing')
  assert.equal(await ev("document.querySelector('.meeting-answer-pages span').textContent"), `${count + 1} / ${count + 3}`)
  await next(); await next(); assert.ok((await text()).includes('SAVED PAGE THREE'))
  await click('Chat'); await frames()
  await send('Emulation.setDeviceMetricsOverride', { width: 400, height: 620, deviceScaleFactor: 1, mobile: false }); await frames()
  assert.equal(await ev('document.documentElement.scrollWidth>innerWidth'), false)
  assert.ok(await ev("{const r=document.querySelector('.meeting-answer-pages').getBoundingClientRect();r.left>=0&&r.right<=innerWidth}"))
  assert.ok(await ev("document.querySelector('.meeting-answer').getBoundingClientRect().height>=300"))
  await shot('meeting-answer-pages-400px')
  await click('Clear'); await frames(); assert.equal(await ev("!!document.querySelector('.meeting-answer-content')"), false)
  await back(); assert.ok((await text()).includes('SAVED PAGE THREE'), 'Clear hides only display, not saved pages')
  await send('Emulation.setDeviceMetricsOverride', { width: 880, height: 740, deviceScaleFactor: 1, mobile: false }); await frames()
  await ev('delete window.fixture.answerText;delete window.fixture.answerModel')
}
